from lib import *
S = SS('x89')
steps = [
    step("Page、Slice、List 各发几条 SQL(ord 表 50 万行,status 有 4 个取值,每个约 125000 行)。findByStatus(\"NEW\", PageRequest.of(0, 20)) 返回 Page:2 条 SQL——一条 select … where status=? limit ?,一条 select count(o1_0.id) from ord … where status=?,总数 125000、总页数 6250。返回 Slice 的 findSliceByStatus:只有 1 条 select … limit ?,Slice 只知道内容 20 行和 hasNext=true,不知道总数。返回 List 的 findListByStatus:同样 1 条。@Query(\"select o from Ord o where o.status = ?1\") 返回 Page,不写 countQuery:也是 2 条,count 查询是 Spring Data 自己从 @Query 推出来的 select count(o1_0.id) …;显式写 countQuery 的结果完全一样。代价上的区别是 count:Page 的第二条要数完 125000 行里符合条件的行。", t=tl(S(1)), mark=lidx(S(1), 'findSliceByStatus', 'findListByStatus'), done=lidx(S(1), 'findByStatus("NEW"', '不写 countQuery', 'countQuery = …'), b=bars([['返回 Page 时发出的 SQL 条数', 2, '2'], ['返回 Slice 时发出的 SQL 条数', 1, '1'], ['返回 List 时发出的 SQL 条数', 1, '1'], ['@Query 返回 Page(没写 countQuery)的 SQL 条数', 2, '2']], 2, mark=[1, 2], done=[0, 3]), kv=KV([['Page', '数据 + count 两条 SQL,知道总数'], ['Slice', '一条 SQL,只知道有没有下一页'], ['List', '一条 SQL'], ['@Query 的 count', '不写 countQuery 也会自动推出来']], ['Slice'])),
    step("什么时候 Page 可以不发 count 查询。总共 5 行、第 0 页每页 20:内容 5 行,只发了 1 条 SQL(没有 count),Page 自己算出总数 5。总共 30 行、第 0 页每页 20:内容刚好满一页 20 行,Spring Data 无法确定是否还有更多,于是发 count,2 条 SQL,总数 30、总页数 2。同样 30 行、第 1 页:内容 10 行不足一页,只发 1 条 SQL(offset 加内容行数就是总数),SQL 里是 limit ?,?。超出末页的第 5 页:内容 0 行,又发了 count,2 条 SQL。规律:内容不足一页(非空)时可以省掉 count;满页或空页必须再数一次。", t=tl(S(2)), mark=lidx(S(2), '满了', '超出末页'), done=lidx(S(2), '总共只有 5 行', '最后一页只有 10 行'), b=bars([['只有 5 行的第 0 页:SQL 条数', 1, '1'], ['第一页满了:SQL 条数', 2, '2'], ['最后一页不足一页:SQL 条数', 1, '1'], ['超出末页:SQL 条数', 2, '2']], 2, mark=[1, 3], done=[0, 2]), kv=KV([['内容不足一页', '省掉 count,1 条 SQL'], ['内容满一页', '要 count,2 条'], ['空页', '要 count,2 条'], ['总数', '不足一页时由 offset + 内容行数得出']], ['内容不足一页'])),
    step("排序的几个坑。Sort.by(\"amount\") 正常生成 order by o1_0.amount limit ?;Sort.by(\"nope\") 抛 PropertyReferenceException: No property 'nope' found for type 'Ord',一条 SQL 都没发;想注入的 Sort.by(\"amount; drop table ord\") 被拒绝,抛 InvalidDataAccessApiUsageException,提示排序表达式只能是属性引用或 select 里的别名。原生查询要注意:Sort.by(\"createdAt\")(Java 属性名)拼进 SQL 变成 order by createdAt,MySQL 报 Unknown column 'createdAt' in 'order clause';改成列名 Sort.by(\"created_at\") 才能执行,count 是 select count(1)。更隐蔽的是排序不唯一:按 bucket(只有 10 个取值)排序、每页 20 行翻 50 页,共读到 1000 行,但不同的行只有 896 个——有重复也就有漏掉;把 id 加进去 Sort.by(\"bucket\", \"id\") 之后 1000 行全部不同。", t=tl(S(3)), mark=lidx(S(3), 'Sort.by("nope")', '想注入', 'Sort.by("createdAt")', '按 bucket: ASC:共读到'), done=lidx(S(3), 'Sort.by("amount")', 'Sort.by("created_at")', 'bucket: ASC,id: ASC'), b=bars([['按 bucket 排序翻 50 页读到的行数', 1000, '1000'], ['其中不同的行数', 896, '896'], ['按 bucket, id 排序翻 50 页不同的行数', 1000, '1000']], 1000, done=[0, 2], mark=[1]), kv=KV([['不存在的属性', 'PropertyReferenceException,不发 SQL'], ['注入', '被 InvalidDataAccessApiUsageException 拒绝'], ['原生查询的 Sort', '要用列名 created_at,不是属性名 createdAt'], ['排序不唯一', '翻页会重复和漏行,要加唯一列(如 id)作为末位']], ['排序不唯一'])),
    step("深分页的代价(50 万行,按 id 排序,每页 20 行,各取 5 次中位数)。第 0 页(offset 0):Slice 0.6 ms,Page(多一条 count)43.6 ms。第 1000 页(offset 20000):Slice 4.7 ms,Page 47.8 ms。第 12500 页(offset 250000):Slice 45.1 ms,Page 87.6 ms。第 24999 页(offset 499980):Slice 91.7 ms,Page 132.2 ms。offset 越大越慢,因为 MySQL 要先数过前面所有的行;Page 比 Slice 固定多出约 42 到 43 ms 的 count(算出来的差)。换成 keyset(where id > ? order by id limit 20):从 id > 0 到 id > 499980,耗时一直是 0.6 到 0.9 ms。", t=tl(S(4)), mark=lidx(S(4), '第 24999 页', 'keyset:where id > 499980'), done=lidx(S(4), '第 0 页', 'keyset:where id > 0'), b=bars([['Slice offset 0(ms)', 0.6, '0.6'], ['Slice offset 250000(ms)', 45.1, '45.1'], ['Slice offset 499980(ms)', 91.7, '91.7'], ['Page offset 499980(ms)', 132.2, '132.2'], ['keyset id > 499980(ms)', 0.7, '0.7']], 132.2, mark=[2, 3], done=[0, 4], cur=[1]), kv=KV([['offset 越大越慢', '0.6 ms → 91.7 ms(Slice)'], ['Page 的 count', '固定多约 43 ms(50 万行)'], ['keyset', '一直 0.6 到 0.9 ms'], ['代价', 'keyset 只能「下一页」,不能跳页']], ['offset 越大越慢'])),
    step("join fetch 加分页。@Query(\"select c from Customer c join fetch c.orders\") 返回 Page<Customer>,每页 5 个 customer:Hibernate 打出警告 HHH90003004: firstResult/maxResults specified with collection fetch; applying in memory——查询里没有 limit,是把所有 join 出来的行(20000 行)读进内存再分页。更糟的是 count:没有写 countQuery 时,自动推出来的是 select count(c1_0.id) from customer c1_0 join ord … on …,数的是 join 之后的行数,Page 里总数是 20000(总页数 4000),而实际只有 50 个 customer。把 countQuery 指向 select count(c) from Customer c,总数是 50、总页数 10。集合 fetch 与分页不要放在一个查询里。", t=tl(S(5)), mark=lidx(S(5), '@Query("select c from Customer c join fetch c.orders") Page', 'HHH90003004'), done=lidx(S(5), 'countQuery 指向'), b=bars([['没写 countQuery:Page 总数', 20000, '20000(错)'], ['写了 countQuery:Page 总数', 50, '50(对)'], ['两种情况的 customer 实际个数', 50, '50']], 20000, mark=[0], done=[1, 2]), kv=KV([['collection fetch + 分页', 'HHH90003004:在内存里分页,查询里没有 limit'], ['不写 countQuery', 'count 数的是 join 之后的行数:20000'], ['写 countQuery', '总数 50,总页数 10'], ['建议', '先分页取 id,再用 join fetch 取子集合']], ['collection fetch + 分页'])),
]
A = mkartx('x89', 89, 'Spring,Data,JPA,分页,Query,count,排序,真实验证,动画演示',
    '实测 Spring Data JPA 的 @Query 与分页:Page 是数据加 count 两条 SQL,Slice 和 List 只有一条;内容不足一页时可以省掉 count;原生查询的 Sort 要用列名;排序不唯一翻 50 页只读到 896 个不同行;offset 499980 的 Slice 要 91.7 ms 而 keyset 一直 0.7 ms;join fetch 加分页在内存里分页且 count 数的是 join 行数。',
    'Page 和 Slice 差在哪?count 查询什么时候会省掉?原生查询的排序为什么报 Unknown column?翻页翻着翻着为什么重复了?深分页怎么这么慢?join fetch 加 Pageable 会怎样?这篇在 Spring Boot 4.0.8、Hibernate 7、MySQL 的 50 万行表上逐个实测。',
    [('896 / 1000', '按只有 10 个取值的列排序翻 50 页,读到 1000 行但只有 896 个不同的行'), ('91.7 ms vs 0.7 ms', 'offset 499980 的 Slice 与 keyset(id > 499980)的耗时'), ('20000 vs 50', 'join fetch 加分页时,没写 countQuery 的总数与写了之后的总数')],
    [('Page、Slice、List', '<p>Page 两条 SQL(数据加 count),Slice 与 List 一条;@Query 的 count 会自动推出来。</p>'),
     ('省掉 count', '<p>内容不足一页(且非空)时,Page 靠 offset 加内容行数算出总数,不发 count。</p>'),
     ('排序', '<p>原生查询的 Sort 要写列名;排序列不唯一会让翻页重复和漏行,要补上唯一列。</p>'),
     ('深分页', '<p>offset 越大越慢;keyset 的耗时与位置无关,但只能翻下一页。</p>'),
     ('join fetch 加分页', '<p>在内存里分页,count 数的是 join 后的行数,要显式写 countQuery。</p>')],
    steps,
    [ENV_X + '(Hibernate 7、Spring Data JPA 随 spring-boot-starter-data-jpa;MySQL 是本机自己起的 26.7.0 实例)。ord 表 500000 行(用递归 CTE 生成),status 4 个取值、索引 ix_ord_status,前 20000 行属于 50 个 customer;SQL 来自 Hibernate 的 StatementInspector;第四节每项取 5 次中位数,前几节的单次耗时受 JIT 影响没有引用;JVM -Xmx2g',
     '没有验证:PostgreSQL 等其他数据库的 limit/offset 行为;复合索引能否让 order by 省掉 filesort(没有看 EXPLAIN);Spring Data 4 新增的 ScrollPosition / Window 滚动 API(keyset 的官方写法);Page 的 count 在大表上的优化(近似计数、缓存);原生查询里 countQuery 写法的其他差别;@EntityGraph 与分页的配合(见第 91 篇)'],
    '@Query 与分页')
